            uniq_cands=[(c,cl) for c,cl in cs if cl and len(cl)>1 and freq[c]==1]
            return n, sorted(tgt_color), [rc for rc in rec_comps], [(c,len(cl),min(p[0] for p in cl),max(p[0] for p in cl)) for c,cl in cs if c!=rec_comps[0][0]], uniq_cands
