# Rebuild cleanly. Focus: which demo pairs have duplicates, what are their shapes/colors/positions, and target.
for n in ['1','2','3','4','5']:
    gi=G[f'Demo pair {n} input']; go=G[f'Demo pair {n} output']
    cs,bg=comps_of(gi)
    freq=Counter(c for _,cl in cs)
    grp={}
    for c,cl in cs: grp.setdefault(norm(cl),[]).append((c,len(cl)))
    print('=== pair',n,'bg',bg)
    for k,vv in sorted(grp.items()):
        if len(vv)>1:
            print('  dupshape(k={}) colors/sizes:',k,vv)
    touched={(y,x):(gi[y][x],go[y][x]) for y in range(len(gi)) for x in range(len(gi[0])) if gi[y][x]!=go[y][x]}
    newcol=set(touched.values())
    # find changed comp
    ch_comp={}
    for (y,x),(a,b) in touched.items():
        pass
    # show which component color is recolored: group touched by original color a
    from collections import defaultdict as dd
    cols=dd(int)
    for (y,x),(a,b) in touched.items(): cols[a]+=1
    print('  recolored-from-colors:',dict(cols),'->new:',sorted(newcol))
    # distances to the largest single-occurrence comp of size>1
    uniq=[(c,cl) for c,cl in cs if freq[c]==1 and len(cl)>1]
    tgt=max(uniq,key=lambda t:len(t[1])) if uniq else None
    def ctr(cl): return sum(p[0] for p in cl)/len(cl), sum(p[1] for p in cl)/len(cl)
    tt=ctr(tgt[1]) if tgt else None
    print('  unique large comps:',[(c,(min(p[0] for p in cl),max(p[0] for p in cl)),tt) for c,cl in uniq])

