import os,re,json
from collections import Counter, deque
def load():
    d=os.path.normpath(os.environ['RLM_SESSION_DIR'])
    t=open(d+'/../../sessions/'+os.path.basename(d)+'.jsonl').read().replace('\\n','\n'); G={}
    for m in re.finditer(r'(Demo pair \d+ (?:input|output)|Test input) \((\d+)x(\d+)\):\n',t):
        k,h,w=m[1],int(m[2]),int(m[3])
        rows=[r.split() for r in t[m.end():].split('\n')[:h]]
        if k not in G and all(len(r)==w and all(x.isdigit() for x in r) for r in rows):
            G[k]=[[int(x) for x in r] for r in rows]
    return G
G=load()
def comps_of(g,bg=None):
    if bg is None: bg=Counter(x for r in g for x in r).most_common(1)[0][0]
    h,w=len(g),len(g[0]); seen=[[False]*w for _ in range(h)]; out=[]
    for i in range(h):
        for j in range(w):
            if g[i][j]!=bg and not seen[i][j]:
                c=g[i][j]; q=deque([(i,j)]); seen[i][j]=True; cells=[]
                while q:
                    y,x=q.popleft(); cells.append((y,x))
                    for dy,dx in((1,0),(-1,0),(0,1),(0,-1)):
                        ny,nx=y+dy,x+dx
                        if 0<=ny<h and 0<=nx<w and not seen[ny][nx] and g[ny][nx]==c:
                            seen[ny][nx]=True; q.append((ny,nx))
                out.append((c,cells))
    return out,bg
def norm(cells):
    ys=[p[0] for p in cells]; xs=[p[1] for p in cells]
    return tuple(sorted((y-min(ys),x-min(xs)) for y,x in cells))
def min_dist(a,b): return min(abs(yy-cy)+abs(xx-cx) for yy,xx in a for cy,cx in b)
for n in ['1','2','3','4','5']:
    gi=G[f'Demo pair {n} input']; go=G[f'Demo pair {n} output']
    cs,bg=comps_of(gi)
    grp={}
    for c,cl in cs: grp.setdefault(norm(cl),[]).append((c,cl))
    touched={(y,x):(gi[y][x],go[y][x]) for y in range(len(gi)) for x in range(len(gi[0])) if gi[y][x]!=go[y][x]}
    changedcols={v for _,v in touched.values()}
    cand=[k for k,v in grp.items() if len(v)==2]
    best=max(cand,key=lambda kv:max(sum(len(cc) for _,cc in kv)))
    mems=list(best[1])
    print('=== pair',n)
    rec_mems=[m for m in mems if any(cell in set(m[1]) for cell,_ in touched.values())]
    tgt=[cl for cl_,cl in [(cs[i],cs[j]) for i in range(len(cs)) for j in range(i+1,len(cs))] if False]
    tgtcomps=[cl for c,cl in cs if c in changedcols]
    for idx,m in enumerate(mems):
